import{_ as i,a0 as u,w as l,s as a,ao as s,I as o,a1 as p,A as r,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在 Ubuntu 15.04 上安装 Justniffer | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 15.04 上安装 Justniffer | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 15.04 上安装 Justniffer | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 15.04 上安装 Justniffer | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150918 Install Justniffer In Ubuntu 15.04","title":"在 Ubuntu 15.04 上安装 Justniffer","tag":"201510","desc":""},"relativePath":"201510/20150918 Install Justniffer In Ubuntu 15.04.md","filePath":"[post].md"}'),f={name:"201510/20150918 Install Justniffer In Ubuntu 15.04.md"};function d(m,t,c,g,h,w){const n=u("Link");return l(),a("div",null,[t[16]||(t[16]=s('<h1 id="在-ubuntu-15-04-上安装-justniffer" tabindex="-1">在 Ubuntu 15.04 上安装 Justniffer <a class="header-anchor" href="#在-ubuntu-15-04-上安装-justniffer" aria-label="Permalink to “在 Ubuntu 15.04 上安装 Justniffer”">​</a></h1><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p><img src="http://1426826955.rsc.cdn77.org/wp-content/uploads/2015/09/monitoring1.jpg" alt=""></p>',3)),o("p",null,[p(n,{href:"http://sourceforge.net/projects/justniffer/?source=directory"},{default:r(()=>[...t[0]||(t[0]=[e("Justniffer",-1)])]),_:1}),t[1]||(t[1]=e(" 是一个可用于替代 Snort 的网络协议分析器。它非常流行，可交互式地跟踪/探测一个网络连接。它能从实时环境中抓取流量，支持 “lipcap” 和 “tcpdump” 文件格式。它可以帮助用户分析一个用 wireshark 难以抓包的复杂网络。尤其是它可以有效的帮助你分析应用层流量，能提取类似图像、脚本、HTML 等 http 内容。Justniffer 有助于理解不同组件之间是如何通信的。",-1))]),t[17]||(t[17]=s(`<h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>Justniffer 可以收集一个复杂网络的所有流量而不影响系统性能，这是 Justniffer 的一个优势，它还可以保存日志用于之后的分析，Justniffer 其它一些重要功能包括：</p><ol><li><p>可靠的 TCP 流重建</p><p>它可以使用主机 Linux 内核的一部分用于记录并重现 TCP 片段和 IP 片段。</p></li><li><p>日志</p><p>保存日志用于之后的分析，并能自定义保存内容和时间。</p></li><li><p>可扩展</p><p>可以通过外部的 python、 perl 和 bash 脚本扩展来从分析报告中获取一些额外的结果。</p></li><li><p>性能管理</p><p>基于连接时间、关闭时间、响应时间或请求时间等提取信息。</p></li></ol><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>Justniffer 可以通过 PPA 安装：</p><p>运行下面命令添加库：</p><pre><code>$ sudo add-apt-repository ppa:oreste-notelli/ppa
</code></pre><p>更新系统：</p><pre><code>$ sudo apt-get update
</code></pre><p>安装 Justniffer 工具：</p><pre><code>$ sudo apt-get install justniffer
</code></pre><p>make 的时候失败了，然后我运行下面的命令并尝试重新安装服务</p><pre><code>$ sudo apt-get -f install
</code></pre><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>首先用 -v 选项验证安装的 Justniffer 版本，你需要用超级用户权限来使用这个工具。</p><pre><code>$ sudo justniffer -V
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/j.png" alt="j"></p><p><strong>1、 以类似 apache 的格式导出 eth1 接口流量，显示到终端</strong></p><pre><code>$ sudo  justniffer -i eth1
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0013.png" alt="Selection_001"></p><p><strong>2、 可以用下面的选项跟踪正在运行的 tcp 流</strong></p><pre><code>$ sudo  justniffer -i eth1 -r
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0023.png" alt="Selection_002"></p><p><strong>3、 获取 web 服务器的响应时长</strong></p><pre><code>$ sudo justniffer -i eth1 -a &quot; %response.time&quot;
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0033.png" alt="Selection_003"></p><p><strong>4、 使用 Justniffer 读取一个 tcpdump 抓取的文件</strong></p><p>首先，用 tcpdump 抓取流量。</p><pre><code>$ sudo tcpdump -w /tmp/file.cap -s0 -i eth0
</code></pre><p>然后用 Justniffer 访问数据</p><pre><code>$ justniffer -f file.cap
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0056.png" alt="Selection_005"></p><p><strong>5、 只抓取 http 数据</strong></p><pre><code>$ sudo justniffer -i eth1 -r -p &quot;port 80 or port 8080&quot;
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0064.png" alt="Selection_006"></p><p><strong>6、 获取一个指定主机 http 数据</strong></p><pre><code>$ justniffer -i eth1 -r -p &quot;host 192.168.1.250 and tcp port 80&quot;
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0074.png" alt="Selection_007"></p><p><strong>7、 以更精确的格式抓取数据</strong></p><p>当你输入 <strong>justniffer -h</strong> 的时候你可以看到很多用于以更精确的方式获取数据的格式关键字</p><pre><code>$ justniffer -h
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0083.png" alt="Selection_008"></p><p>让我们用 Justniffer 根据预先定义的参数提取数据</p><pre><code>$ justniffer -i eth1 -l &quot;%request.timestamp %request.header.host %request.url %response.time&quot;
</code></pre><p>示例输出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0094.png" alt="Selection_009"></p><p>其中还有很多你可以探索的选项。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Justniffer 是一个很好的用于网络测试的工具。在我看来对于那些用 Snort 来进行网络探测的用户来说，Justniffer 是一个更简单的工具。它提供了很多 <strong>格式关键字</strong> 用于按照你的需要精确地提取数据。你可以用 .cap 文件格式记录网络信息，之后用于分析监视网络服务性能。</p><p><strong>参考资料：</strong></p>`,58)),o("ul",null,[o("li",null,[p(n,{href:"http://justniffer.sourceforge.net/"},{default:r(()=>[...t[2]||(t[2]=[e("Justniffer 官网",-1)])]),_:1})])]),t[18]||(t[18]=o("hr",null,null,-1)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),p(n,{href:"http://www.unixmen.com/install-justniffer-ubuntu-15-04/"},{default:r(()=>[...t[3]||(t[3]=[e("http://www.unixmen.com/install-justniffer-ubuntu-15-04/",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),p(n,{href:"http://www.unixmen.com/author/rajneesh/"},{default:r(()=>[...t[5]||(t[5]=[e("Rajneesh Upadhyay",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),p(n,{href:"http://mutouxiaogui.cn/blog"},{default:r(()=>[...t[6]||(t[6]=[e("ictlyh",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创编译，",-1)),p(n,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const _=i(f,[["render",d]]);export{T as __pageData,_ as default};
